import json
import os
import unittest


class TestExperimentEvidenceSchema(unittest.TestCase):
    def setUp(self) -> None:
        # Ensure evidence is generated by running run.py beforehand in harness.
        self.evidence_dir = os.environ.get("BOOKMAS_EVIDENCE_DIR", "/evidence")
        self.results_path = os.path.join(self.evidence_dir, "results.json")

    def test_results_file_exists(self) -> None:
        self.assertTrue(os.path.exists(self.results_path), f"Missing {self.results_path}")

    def test_results_schema(self) -> None:
        with open(self.results_path, "r", encoding="utf-8") as f:
            data = json.load(f)

        # Top-level keys
        self.assertIn("chapter", data)
        self.assertIn("experiment_id", data)
        self.assertIn("environment", data)
        self.assertIn("runs", data)

        self.assertEqual(data["chapter"], 3)
        self.assertEqual(data["experiment_id"], "ch3-failure-modes-of-autonomous-ai-in-finance")

        env = data["environment"]
        self.assertIsInstance(env, dict)
        self.assertIn("os", env)
        self.assertIn("python", env)

        runs = data["runs"]
        self.assertIsInstance(runs, list)
        self.assertGreater(len(runs), 0)

        # Track baseline/treatment presence per workload
        variants_by_workload = {}

        for run in runs:
            self.assertIn("variant", run)
            self.assertIn("workload_id", run)
            self.assertIn("run_id", run)
            self.assertIn("success", run)
            self.assertIn("metrics", run)

            variant = run["variant"]
            self.assertIn(variant, ("baseline", "treatment"))

            wid = run["workload_id"]
            variants_by_workload.setdefault(wid, set()).add(variant)

            self.assertIsInstance(run["success"], bool)

            metrics = run["metrics"]
            self.assertIsInstance(metrics, dict)
            # At least one metric per run
            self.assertGreater(len(metrics), 0)
            for k, v in metrics.items():
                # Metric values must be numbers (no bools, no None, no containers)
                self.assertIsInstance(v, (int, float), msg=f"Metric {k} is not numeric: {v!r}")
                # Exclude booleans (they are instances of int in Python)
                self.assertNotIsInstance(v, bool, msg=f"Metric {k} must not be bool")

        # Ensure each known workload has both baseline and treatment
        expected_wids = {
            "wl-3.2-drift-credit-risk",
            "wl-3.3-rl-credit-limits",
            "wl-3.4-feedback-loop-trading",
            "wl-3.5-adversarial-fraud-and-llm",
            "wl-3.6-fairness-credit-approvals",
            "wl-3.7-emergent-llm-agent-behaviour",
            "wl-3.8-multi-stage-failure-cascade",
        }
        for wid in expected_wids:
            self.assertIn(wid, variants_by_workload, msg=f"Missing runs for {wid}")
            variants = variants_by_workload[wid]
            self.assertIn("baseline", variants, msg=f"Missing baseline for {wid}")
            self.assertIn("treatment", variants, msg=f"Missing treatment for {wid}")


if __name__ == "__main__":
    unittest.main()
